    Tuple resultTuple = sortMergeJoinResultIterator.next();
    long elapsed = System.currentTimeMillis() - startTime;
    assertTrue(resultTuple == null);
    assertTrue(sortMergeJoinResultIterator.isJoinResultNullBecauseOneSideNull());
